// Isolated benchmark only; valid identities, no external data or Provider.
import {identify} from '../../core/dedupe.js';
import {recordIndex,blockIndex,sourceCount} from '../../core/idb-repository.js';
export async function seedScale(s,size){await s.finishFoundation();await s.setFilterMode('off');const existing=await s.repository.transaction(false,t=>t.count('records'));if(!existing)await s.capture({epoch:(await s.status()).epoch,adapterVersion:'0.3.0',chat:{id:'scale-seed',url:'https://chatgpt.com/c/scale-seed',title:'Synthetic scale seed'},messages:[{sourceMessageId:'scale-seed-0',pageOrder:1,originalText:'Synthetic scale seed'}]});const base=await s.repository.transaction(false,async t=>{const r=(await t.page('records',{limit:1})).rows[0].value.value,b=(await t.get('blocks','block:'+r.id)).value;return {r,b,m:await t.get('inputStates',b.id),d:(await t.get('documents',b.documentId)).value};});
 for(let start=Math.max(1,existing);start<size;start+=200){const prepared=await Promise.all(Array.from({length:Math.min(200,size-start)},async(_,offset)=>{const i=start+offset,group=Math.floor(i/200),chatId='scale-chat-'+group,documentId='document:scale-'+group,id='scale-record-'+String(i).padStart(8,'0'),text='Synthetic scale body '+i+' · Evidence remains local.',identity=await identify(chatId,'scale-message-'+i,text),time=new Date(1609459200000+i*1000).toISOString(),r={...base.r,...identity,id,chatId,chatUrl:'https://chatgpt.com/c/'+chatId,chatTitle:'Scale title '+group,sourceMessageId:'scale-message-'+i,originalText:text,sourceSentAt:time,capturedAt:time,timeSource:'chatgpt_response_create_time',timeConfidence:'high',pageOrder:i%200+1,conversationOrder:i%200+1},b={...base.b,id:'block:'+id,documentId,sourceRecordId:id,originalTextReference:id,provenance:[{sourceRecordId:id}],provenanceSignature:JSON.stringify([{sourceRecordId:id}])};return {i,group,r,b};}));
  await s.repository.transaction(true,async t=>{for(const {i,group,r,b}of prepared){await t.put('records',{id:r.id,value:r});await t.put('recordIndex',recordIndex(r,i));await t.put('blocks',{id:b.id,value:b});await t.put('blockIndex',blockIndex(b,i,[r]));await t.put('inputStates',{...base.m,id:b.id,documentId:b.documentId,sourceRecordIds:[r.id],deltaSequence:i+1});await t.put('sourceCounts',sourceCount(b.documentId,r.sourceKey,[r],[b],r.chatId));if(i===1||i%200===0){const d={...base.d,id:b.documentId,sourceConversationId:r.chatId,originalConversationTitle:r.chatTitle,firstSourceSentAt:r.sourceSentAt,lastSourceSentAt:r.sourceSentAt},key=[-Date.parse(r.sourceSentAt),d.id];await t.put('documents',{id:d.id,sequence:group+1,chatKey:'chatgpt:'+r.chatId,displayKey:key,libraryDisplay:key,archiveDisplay:key,value:d});await t.put('libraryDocuments',{id:d.id,value:d});}}});await new Promise(r=>setTimeout(r,0));
 }
 await s.repository.transaction(true,async t=>{await t.put('meta',{id:'sequence',records:size,blocks:size,documents:Math.ceil(size/200)+1});await t.put('meta',{id:'input-delta-sequence',value:size+1});});return {size,physicalSchema:s.repository.db.version};
}
